OM_uint32 spnego_init_reselect(OM_uint32 *minor_status,
                               spnego_gss_ctx_id_t sc,
                               OM_uint32 acc_negState,
                               gss_OID supportedMech,
                               gss_buffer_t *responseToken,
                               gss_buffer_t *mechListMIC,
                               OM_uint32 *negState,
                               send_token_flag *tokflag) {
    OM_uint32 major_status = GSS_S_FAILURE;
    gss_OID found_mech = GSS_C_NO_OID;

    if (minor_status == NULL || sc == NULL ||
        responseToken == NULL || negState == NULL || tokflag == NULL) {
        if (minor_status)
            *minor_status = 0;
        return GSS_S_BAD_ARGUMENT;
    }

    /* Delete existing context */
    gss_delete_sec_context(&major_status, minor_status, &sc->internal_context);
    if (major_status != GSS_S_COMPLETE) {
        *minor_status = 0;
        return major_status;
    }

    /* Check if supportedMech is in the mechanism set */
    if (gss_test_oid_set_member(minor_status, supportedMech, sc->mech_set, &found_mech) != GSS_S_COMPLETE ||
        found_mech == GSS_C_NO_OID) {
        *minor_status = 0;
        return GSS_S_BAD_MECH;
    }

    sc->selected_mech = found_mech;

    if (acc_negState != GSS_C_NO_CONTEXT &&
        acc_negState != GSS_INITIATOR_REQ && acc_negState != GSS_ACCEPTOR_REQ) {
        *minor_status = 0;
        return GSS_S_BAD_SIG;
    }

    sc->neg_state = acc_negState;

    if (responseToken->length > 0 && responseToken->value != NULL) {
        gss_release_buffer(minor_status, responseToken);
    }

    if (mechListMIC != NULL && mechListMIC->length > 0) {
        gss_release_buffer(minor_status, mechListMIC);
    }

    *tokflag = SEND_TOKEN_CONTINUE;

    *negState = sc->neg_state;
    *minor_status = 0;
    return GSS_S_CONTINUE_NEEDED;
}

OM_uint32 spnego_gss_context_reslection(OM_uint32 *minor_status,
                                        spnego_gss_ctx_id_t sc,
                                        OM_uint32 acc_negState,
                                        gss_OID supportedMech,
                                        gss_buffer_t *responseToken,
                                        gss_buffer_t *mechListMIC,
                                        OM_uint32 *negState,
                                        send_token_flag *tokflag) {
    OM_uint32 major_status = GSS_S_COMPLETE;
    gss_OID mech_set;
    OM_uint32 tmp_minor;

    *minor_status = 0;

    if (!sc || !responseToken || !negState || !tokflag) {
        major_status = GSS_S_BAD_ARGUMENT;
        *minor_status = EINVAL;
        return major_status;
    }

    gss_delete_sec_context(&tmp_minor, &sc->internal_context, NULL);

    if (sc->internal_context == NULL) {
        major_status = GSS_S_NO_CONTEXT;
        *minor_status = ENOENT;
        return major_status;
    }

    if (acc_negState != SPNEGO_NEG_STATE_ACCEPTED) {
        *negState = acc_negState;
        major_status = GSS_S_CONTINUE_NEEDED;
        return major_status;
    }

    if (gss_test_oid_set_member(&tmp_minor, supportedMech, sc->supported_mechs, NULL) != GSS_S_COMPLETE) {
        *negState = SPNEGO_NEG_STATE_REJECTED;
        major_status = GSS_S_BAD_MECH;
        *minor_status = EINVAL;
        return major_status;
    }

    sc->current_mech = supportedMech;
    sc->state = GSS_C_NO_CREDENTIAL;

    *negState = SPNEGO_NEG_STATE_COMPLETED;
    *tokflag = SEND_TOKEN_FLAG_SEND;

    if (responseToken->length != 0 || responseToken->value != NULL) {
        responseToken->length = 0;
        responseToken->value = NULL;
    }

    if (mechListMIC != NULL && mechListMIC->length > 0) {
        if (gss_verifyMIC(&tmp_minor, sc->internal_context, mechListMIC->value, mechListMIC->length, NULL, NULL) != GSS_S_COMPLETE) {
            major_status = GSS_S_BAD_SIG;
            *minor_status = EACCES;
            return major_status;
        }
    }

    return major_status;
}

OM_uint32 spnego_gss_init_reselect(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status, tmp_negState = 0;
    gss_OID mech_set = GSS_C_NO_OID_SET;
    OM_uint32 tmp_minor_status = 0;
    OM_uint32 status = GSS_S_BAD_SIG;

    *minor_status = 0;

    if (sc == GSS_C_NO_CONTEXT) {
        return GSS_S_BAD_CONTEXT;
    }

    if (supportedMech == GSS_C_NO_OID) {
        return GSS_S_BAD_NAME;
    }

    if (negState == NULL || tokflag == NULL || responseToken == NULL) {
        return GSS_S_FAILURE;
    }

    if (gss_test_oid_set_member(&tmp_minor_status, supportedMech, mech_set, &tmp_negState) != GSS_S_COMPLETE) {
        return GSS_S_BAD_SIG;
    }

    if (acc_negState != SPNEGO_NG_STATE_ACCEPT) {
        return GSS_S_FAILURE;
    }

    sc->internal_mech = supportedMech;
    sc->neg_state = acc_negState;

    *negState = sc->neg_state;
    *tokflag = SEND_TOKEN_FLAG_ACCEPT;

    return GSS_S_COMPLETE;
}

OM_uint32 spnego_init_context_reselection(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;
    gss_OID_set supported_mechs;
    gss_OID best_mech;

    /* Delete the current security context */
    (void)gss_delete_sec_context(minor_status, &sc, GSS_C_NO_BUFFER);

    /* Check if the supported mechanism is in the mechanism set */
    major_status = gss_caresupportedmech(supportedMech, &supported_mechs);

    if (major_status != GSS_S_COMPLETE) {
        *minor_status = GSS_S_BAD_MECH;
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != GSS_SPNEGO_NSTATE_ACCEPTED) {
        *minor_status = GSS_S_BAD_SIG;
        return GSS_S_BAD_SIG;
    }

    /* Set the internal mechanism */
    best_mech = supportedMech;

    /* Update the negotiation state */
    *negState = GSS_SPNEGO_NSTATE_SELECTED;

    /* Update the token send flag */
    *tokflag = SEND_TOKEN_RESPONSE;

    *minor_status = 0;
    return GSS_S_COMPLETE;
}

OM_uint32 spnego_gss_context_reselect(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;
    gss_OID_set mech_set = GSS_C_NO_OID_SET;
    OM_uint32 tmp_minor = 0;
    OM_uint32 internalMech = 0;

    // Delete the current security context
    gss_delete_sec_context(&tmp_minor, &sc, GSS_C_NO_BUFFER);

    // Check if the supported mechanism is in the mechanism set
    major_status = gss_create_empty_oid_set(&tmp_minor, &mech_set);
    if (major_status != GSS_S_COMPLETE) {
        if (minor_status != NULL)
            *minor_status = tmp_minor;
        return major_status;
    }

    major_status = gss_add_oid_set_member(&tmp_minor, supportedMech, &mech_set);
    if (major_status != GSS_S_COMPLETE) {
        gss_release_oid_set(&tmp_minor, &mech_set);
        if (minor_status != NULL)
            *minor_status = tmp_minor;
        return major_status;
    }

    // Validate negotiation state
    if (acc_negState != GSS_S_CONTINUE_NEEDED) {
        gss_release_oid_set(&tmp_minor, &mech_set);
        if (minor_status != NULL)
            *minor_status = tmp_minor;
        return GSS_S_BAD_SIG;
    }

    // Set internal mechanism
    internalMech = *(OM_uint32 *)supportedMech->elements;

    // Update negotiation state
    if (negState != NULL)
        *negState = GSS_S_COMPLETE;

    // Update token flag
    if (tokflag != NULL)
        *tokflag = SEND_TOKEN_FLAG_INIT;

    gss_release_oid_set(&tmp_minor, &mech_set);

    if (minor_status != NULL)
        *minor_status = 0;

    return GSS_S_COMPLETE;
}
